@IsTest
private class AddressVerificationServiceTest {

    private static final String ENDPOINT = 'callout:FB_Address_API/v2/verify';

    /* ---------- helpers ---------- */

    private static Account newAccount() {
        return new Account(
            Name = 'Address Test',
            BillingStreet = '1 Main St',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'United States'
        );
    }

    private static MockAddressApi mockFor(Integer statusCode, String body) {
        MockAddressApi mock = new MockAddressApi();
        mock.statusCode = statusCode;
        mock.responseBody = body;
        Test.setMock(HttpCalloutMock.class, mock);
        return mock;
    }

    private static String correctedBody() {
        return '{"status":"CORRECTED","address":{"street":"100 Real Ave",' +
               '"city":"Shelbyville","postalCode":"54321","country":"Canada"}}';
    }

    /* ---------- skipped cases ---------- */

    @IsTest
    static void nullStreetIsSkippedWithoutCallout() {
        Account acct = newAccount();
        acct.BillingStreet = null;
        MockAddressApi mock = mockFor(200, '{"status":"VERIFIED"}');

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('SKIPPED', result.status, 'Blank street should be SKIPPED');
        System.assertEquals(false, result.changed, 'Skipped result must not be changed');
        System.assertEquals(0, mock.requests.size(), 'No callout must be made for a blank street');
    }

    @IsTest
    static void whitespaceOnlyStreetIsSkippedWithoutCallout() {
        Account acct = newAccount();
        acct.BillingStreet = '   ';
        MockAddressApi mock = mockFor(200, '{"status":"VERIFIED"}');

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('SKIPPED', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals(0, mock.requests.size(), 'No callout must be made for whitespace street');
    }

    @IsTest
    static void emptyStreetIsSkippedWithoutCallout() {
        Account acct = newAccount();
        acct.BillingStreet = '';
        MockAddressApi mock = mockFor(200, '{"status":"VERIFIED"}');

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('SKIPPED', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals(0, mock.requests.size());
    }

    @IsTest
    static void skippedAccountIsNotModified() {
        Account acct = newAccount();
        acct.BillingStreet = null;
        acct.BillingCity = 'Springfield';
        mockFor(200, correctedBody());

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('SKIPPED', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals(null, acct.BillingStreet, 'Skipped account must not be changed');
        System.assertEquals('Springfield', acct.BillingCity);
    }

    /* ---------- request contract ---------- */

    @IsTest
    static void requestMatchesApiContract() {
        Account acct = newAccount();
        MockAddressApi mock = mockFor(200, '{"status":"VERIFIED"}');

        Test.startTest();
        AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals(1, mock.requests.size(), 'Exactly one callout expected');
        HttpRequest req = mock.requests[0];
        System.assertEquals('POST', req.getMethod(), 'Method must be POST');
        System.assertEquals(ENDPOINT, req.getEndpoint(), 'Endpoint must be the named credential path');
        System.assertEquals('application/json', req.getHeader('Content-Type'), 'Content-Type header required');

        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(req.getBody());
        System.assertEquals(4, body.keySet().size(), 'Body must contain exactly four keys');
        System.assertEquals('1 Main St', body.get('street'));
        System.assertEquals('Springfield', body.get('city'));
        System.assertEquals('12345', body.get('postalCode'));
        System.assertEquals('United States', body.get('country'));
    }

    @IsTest
    static void requestBodyUsesBillingFieldsOfAccount() {
        Account acct = new Account(
            Name = 'Other',
            BillingStreet = '42 Galaxy Rd',
            BillingCity = 'Ankh',
            BillingPostalCode = 'X9Y8',
            BillingCountry = 'Canada'
        );
        MockAddressApi mock = mockFor(200, '{"status":"INVALID"}');

        Test.startTest();
        AddressVerificationService.verify(acct);
