        System.assertEquals(1, mock.requests.size());
        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(mock.requests[0].getBody());
        System.assertEquals('42 Galaxy Rd', body.get('street'));
        System.assertEquals('Ankh', body.get('city'));
        System.assertEquals('X9Y8', body.get('postalCode'));
        System.assertEquals('Canada', body.get('country'));
