    /* ---------- successful responses ---------- */

    @IsTest
    static void verifiedLeavesAccountUntouched() {
        Account acct = newAccount();
        mockFor(200, '{"status":"VERIFIED","address":{"street":"100 Real Ave",' +
                     '"city":"Shelbyville","postalCode":"54321","country":"Canada"}}');

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('VERIFIED', result.status);
        System.assertEquals(false, result.changed, 'VERIFIED must not set changed');
        System.assertEquals('1 Main St', acct.BillingStreet);
