/**
 * Purges FB_Integration_Log__c records on a schedule.
 *
 * Retention rules:
 *   - Non-ERROR logs (DEBUG, INFO, blank, or any other value) are deleted once
 *     they were created more than 30 days ago.
 *   - ERROR logs are kept until they were created more than 180 days ago.
 *
 * Each scheduled run deletes eligible logs synchronously, up to one DML batch
 * of MAX_SYNC_ROWS records. If that limit was reached, the remainder is handed
 * to PurgeBatch, which processes the rest in chunks within governor limits.
 *
 * Runs in system context on purpose: the purge must remove logs regardless of
 * record ownership or sharing.
 */
public without sharing class LogPurgeJob implements Schedulable {

    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String CRON_EXPRESSION = '0 0 2 * * ?';
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final Integer MAX_SYNC_ROWS = 10000;
    private static final Integer BATCH_SIZE = 2000;

    public LogPurgeJob() {
    }

    /**
     * Schedules the purge to run every day at 02:00.
     * @return The Id of the CronTrigger returned by System.schedule.
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_EXPRESSION, new LogPurgeJob());
    }

    // Schedulable entry point.
    public void execute(SchedulableContext sc) {
        DateTime nonErrorCutoff = DateTime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        DateTime errorCutoff = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

        // Level__c can be blank, so the null check is explicit: a bare
        // Level__c != 'ERROR' would silently exclude blank-level logs.
        List<FB_Integration_Log__c> eligible = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :nonErrorCutoff
                    AND (Level__c = null OR Level__c != 'ERROR'))
               OR (CreatedDate < :errorCutoff
                    AND Level__c = 'ERROR')
            LIMIT :MAX_SYNC_ROWS
        ];

        if (!eligible.isEmpty()) {
            // Partial failures are tolerated so one bad record does not stop the rest.
            Database.delete(eligible, false);
        }

        // A full sync window means more records may remain; hand off to the batch.
        if (eligible.size() == MAX_SYNC_ROWS) {
            Database.executeBatch(new PurgeBatch(), BATCH_SIZE);
        }
    }

    /**
     * Schedules the purge to run every day at 02:00.
     * @return The Id of the CronTrigger returned by System.schedule.
     */

    /**
     * Batch that processes the remainder of a large purge in chunks.
     */
    public without sharing class PurgeBatch implements Database.Batchable<SObject> {

        public Database.QueryLocator start(Database.BatchableContext bc) {
            DateTime nonErrorCutoff = DateTime.now().addDays(-NON_ERROR_RETENTION_DAYS);
            DateTime errorCutoff = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

            return Database.getQueryLocator([
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < :nonErrorCutoff
                        AND (Level__c = null OR Level__c != 'ERROR'))
                   OR (CreatedDate < :errorCutoff
                        AND Level__c = 'ERROR')
            ]);
        }

        public void execute(Database.BatchableContext bc, List<SObject> scope) {
            if (scope == null || scope.isEmpty()) {
                return;
            }
            Database.delete(scope, false);
        }

        public void finish(Database.BatchableContext bc) {
            // No post-processing required.
        }
    }
}
