```apex
public class Opportunities extends fflib_SObjectDomain {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String MSG_NEGATIVE_AMOUNT = 'Amount cannot be negative.';
    private static final String MSG_WON_AMOUNT_LOCKED = 'Amount cannot change on a won opportunity.';

    public Opportunities(List<SObject> sObjectList) {
        super(sObjectList, Opportunity.SObjectType);
    }

    /**
     * Insert validation: rule 1 only (there are no existing records on insert).
     */
    public override void onValidate() {
        validateAmountNotNegative();
    }

    /**
     * Update validation:
     *  1. Amount must not be negative.
     *  2. An opportunity whose stage was Closed Won before the update may not have its Amount changed.
     *     Closing a deal as won and changing its amount in the same update is allowed, because the
     *     prior stage is read from the existing (Trigger.oldMap) record.
     * No SOQL is used; all data comes from the trigger context.
     */
    public override void onValidate(Map<Id, SObject> existingRecords) {
        validateAmountNotNegative();

        for (Opportunity opp : (List<Opportunity>) Records) {
            Opportunity existing = (Opportunity) existingRecords.get(opp.Id);
            if (existing == null) {
                continue;
            }
            if (existing.StageName == STAGE_CLOSED_WON && opp.Amount != existing.Amount) {
                rejectAmount(MSG_WON_AMOUNT_LOCKED, opp);
            }
        }
    }

    private void validateAmountNotNegative() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                rejectAmount(MSG_NEGATIVE_AMOUNT, opp);
            }
        }
    }

    /**
     * Records the error through the fflib helper (visible in fflib_SObjectDomain.Errors for unit
     * tests) and attaches it to the Amount field of this record only, so the platform rejects
     * only the offending record and the rest of the DML still saves.
     */
    private void rejectAmount(String message, Opportunity opp) {
        error(message, opp, Opportunity.Amount);
        opp.addError(Opportunity.Amount, message);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }
}
