public with sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load and drop opportunities that are already Closed Won.
        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : OpportunitiesSelector.newInstance().selectById(opportunityIds)) {
            if (opp.StageName != 'Closed Won') {
                toClose.add(opp);
            }
        }

        if (toClose.isEmpty()) {
            return 0;
        }

        // One unit of work for both the opportunity updates and the events.
        // Events registered as "publish after success" are only published
        // by fflib after the DML for this unit of work has committed.
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Date closeDate = Date.today();

        for (Opportunity opp : toClose) {
            opp.StageName = 'Closed Won';
            opp.CloseDate = closeDate;
            uow.registerDirty(opp);

            uow.registerPublishAfterSuccessTransaction(
                new Deal_Won__e(
                    Opportunity_Id__c = String.valueOf(opp.Id),
                    Amount__c = opp.Amount
                )
            );
        }

        // If the commit fails, the exception propagates and no event is published.
        uow.commitWork();

        return toClose.size();
    }
}
