```javascript
import { LightningElement, wire } from 'lwc';
import {
    subscribe,
    unsubscribe,
    publish,
    MessageContext,
    APPLICATION_SCOPE
} from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @wire(MessageContext)
    messageContext;

    subscription = null;
    recordId = null;

    get hasSelection() {
        return !!this.recordId;
    }

    connectedCallback() {
        this.subscribeIfNeeded();
    }

    renderedCallback() {
        // The wired message context may arrive after connectedCallback has run.
        this.subscribeIfNeeded();
    }

    disconnectedCallback() {
        this.unsubscribeIfNeeded();
    }

    subscribeIfNeeded() {
        // Hold at most one subscription, and only once the message context is known.
        if (!this.messageContext || this.subscription) {
            return;
        }
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeIfNeeded() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    handleMessage(message) {
        this.recordId = message && message.recordId ? message.recordId : null;
    }

    handleClear() {
        if (!this.messageContext) {
            return;
        }
        publish(this.messageContext, ACCOUNT_SELECTED, { recordId: null });
    }
}
