    private static final String STATUS_IMPORTED = 'Imported';

    /**
     * Stages and processes one NPSP Data Import record per gift, in input order.
     * Rows that NPSP rejects do not stop the others; their result carries NPSP's failure message.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Pre-build one result per input gift so output order always matches input order.
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult r = new ImportResult();
            r.success = false;
            results.add(r);
        }

        // 1. Stage one Data Import record per gift.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        List<Integer> stagedIndex = new List<Integer>();
        for (Integer i = 0; i < gifts.size(); i++) {
            staged.add(buildDataImport(gifts[i]));
            stagedIndex.add(i);
        }

        // Partial-success insert so one bad staging row cannot block the rest.
        Database.SaveResult[] saveResults = Database.insert(staged, false);
        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();
        Map<Id, Integer> indexById = new Map<Id, Integer>();
        for (Integer i = 0; i < saveResults.size(); i++) {
            Integer resultIdx = stagedIndex[i];
            Database.SaveResult sr = saveResults[i];
            if (sr.isSuccess()) {
                toProcess.add(staged[i]);
                indexById.put(sr.getId(), resultIdx);
            } else {
                results[resultIdx].errorMessage = summariseErrors(sr.getErrors());
            }
        }

        if (toProcess.isEmpty()) {
            return results;
        }

        // 2. Process synchronously with NPSP's data import API using the org's Data Import settings.
        npsp__Data_Import_Settings__c diSettings = npsp__Data_Import_Settings__c.getOrgDefaults();
        npsp.BDI_DataImport_API.processDataImportRecords(diSettings, toProcess, false);

        // 3. Read NPSP's results back from the staged records.
        Set<Id> ids = indexById.keySet();
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>(
            [
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :ids
            ]
        );

        // 4. Build results from the processed Data Import records.
        for (Id diId : indexById.keySet()) {
            Integer idx = indexById.get(diId);
            ImportResult r = results[idx];
            npsp__DataImport__c di = processed.get(diId);

            if (di == null) {
                r.success = false;
                r.errorMessage = 'Data Import record was not found after processing.';
                continue;
            }

            r.contactId = di.npsp__Contact1Imported__c;
            r.opportunityId = di.npsp__DonationImported__c;
            r.success = (di.npsp__Status__c == STATUS_IMPORTED);

            if (r.success) {
                r.errorMessage = null;
            } else {
                String failure = di.npsp__FailureInformation__c;
                if (String.isBlank(failure)) {
                    failure = 'NPSP did not import this row (status: '
                        + (di.npsp__Status__c == null ? 'unknown' : di.npsp__Status__c) + ').';
                }
                r.errorMessage = failure;
            }
        }

        return results;
    }

    /**
     * Maps one web gift onto NPSP's staging fields.
     * A null gift produces an empty staging row, which NPSP will reject with its own message.
     */
    private static npsp__DataImport__c buildDataImport(WebGift g) {
        npsp__DataImport__c di = new npsp__DataImport__c();
        di.npsp__Status__c = STATUS_READY;
        if (g == null) {
            return di;
        }
        di.npsp__Donation_Donor__c = DONOR_CONTACT1;
        di.npsp__Contact1_Firstname__c = g.firstName;
        di.npsp__Contact1_Lastname__c = g.lastName;
        di.npsp__Contact1_Personal_Email__c = g.email;
        di.npsp__Donation_Amount__c = g.amount;
        di.npsp__Donation_Date__c = g.giftDate;
        return di;
    }

    private static String summariseErrors(List<Database.Error> errors) {
        if (errors == null || errors.isEmpty()) {
            return 'Data Import record could not be staged.';
        }
        List<String> messages = new List<String>();
        for (Database.Error e : errors) {
            messages.add(e.getMessage());
        }
        return String.join(messages, '; ');
    }
}
```

