```apex
/**
 * TDTM handler that creates a "Major gift thank-you call" Task when an Opportunity
 * becomes a qualifying major gift (Closed Won and Amount >= 5000).
 *
 * Registration (NPSP Settings > Trigger Configuration > Trigger Handlers):
 *   Class: OPP_MajorGiftFollowUp_TDTM
 *   Object: Opportunity
 *   Trigger Action: AfterInsert;AfterUpdate
 *   Load Order: 5
 *   Asynchronous: false
 *
 * Activation/deactivation is handled by NPSP's TDTM dispatcher via the Trigger Handler
 * record, so no Apex trigger is used and no custom "is active" check is needed here.
 *
 * Bulk behaviour: no SOQL is issued by this handler. All qualifying Tasks are collected
 * into a single list and inserted with one DML statement inside run(). The returned
 * DmlWrapper is empty, so the dispatcher performs no additional DML for this handler.
 * Performing the insert here (rather than only returning it in the wrapper) means the
 * handler behaves identically whether it is invoked by the dispatcher or directly.
 */
public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String WON_STAGE = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';
    private static final Integer DUE_DAYS_AFTER_CLOSE = 3;

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        Boolean isInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);
        Boolean isUpdate = (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate);
        if (!isInsert && !isUpdate) {
            return dmlWrapper;
        }

        // Index prior versions by Id so update detection does not depend on list ordering.
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        if (isUpdate && oldlist != null && !oldlist.isEmpty()) {
            oldById = new Map<Id, Opportunity>((List<Opportunity>) oldlist);
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject so : newlist) {
            Opportunity opp = (Opportunity) so;

            if (!isQualifyingGift(opp)) {
                continue;
            }

            if (isUpdate) {
                Opportunity oldOpp = oldById.get(opp.Id);
                // Already qualified before this edit: do not create another task.
                if (oldOpp != null && isQualifyingGift(oldOpp)) {
                    continue;
                }
            }

            tasksToInsert.add(buildThankYouTask(opp));
        }

        // Single DML statement for the whole batch.
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return dmlWrapper;
    }

    /**
     * A qualifying gift is Closed Won with an Amount at or above the threshold.
     * A null Amount never qualifies.
     */
    private static Boolean isQualifyingGift(Opportunity opp) {
        return opp.StageName == WON_STAGE
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    private static Task buildThankYouTask(Opportunity opp) {
        Date dueDate = (opp.CloseDate == null)
            ? null
            : opp.CloseDate.addDays(DUE_DAYS_AFTER_CLOSE);

        return new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = dueDate
        );
    }
}
