```apex
/**
 * Keeps Account.FB_Open_Case_Count__c equal to the number of the account's open Cases
 * (IsClosed = false). Registered for after insert, after update, after delete and after
 * undelete through Trigger_Action__mdt records.
 *
 * Bulk-safe: per trigger execution it issues at most 2 SOQL queries and at most 1 DML
 * statement, regardless of how many Cases are in the batch.
 *
 * Approach: collect every affected Account Id from the trigger records, recount the open
 * Cases for those accounts with one aggregate query, then update only the accounts whose
 * stored value differs. Accounts with no open Cases are counted as 0.
 *
 * without sharing: the count must reflect all Cases on an account, not only those visible
 * to the user performing the DML. The class only writes the count field.
 */
public without sharing class TA_Case_RollupOpenCount implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            Case c = (Case) record;
            if (!c.IsClosed) {
                addAccountId(accountIds, c.AccountId);
            }
        }
        recount(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        // Match old and new records by Id rather than by list position.
        Map<Id, Case> oldById = new Map<Id, Case>();
        for (SObject record : triggerOld) {
            Case oldCase = (Case) record;
            oldById.put(oldCase.Id, oldCase);
        }

        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            Case newCase = (Case) record;
            Case oldCase = oldById.get(newCase.Id);
            if (oldCase == null) {
                continue;
            }
            // Nothing that affects the count changed.
            if (newCase.AccountId == oldCase.AccountId && newCase.IsClosed == oldCase.IsClosed) {
                continue;
            }
            // The Case was counted against its old Account if it was open there.
            if (!oldCase.IsClosed) {
                addAccountId(accountIds, oldCase.AccountId);
            }
            // The Case is counted against its new Account if it is open there.
            if (!newCase.IsClosed) {
                addAccountId(accountIds, newCase.AccountId);
            }
        }
        recount(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerOld) {
            Case c = (Case) record;
            if (!c.IsClosed) {
                addAccountId(accountIds, c.AccountId);
            }
        }
        recount(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            Case c = (Case) record;
            if (!c.IsClosed) {
                addAccountId(accountIds, c.AccountId);
            }
        }
        recount(accountIds);
    }

    private static void addAccountId(Set<Id> accountIds, Id accountId) {
        if (accountId != null) {
            accountIds.add(accountId);
        }
    }

    /**
     * Recounts open Cases for the given Accounts and updates the stored count where it differs.
     * SOQL 1: aggregate count of open Cases per Account.
     * SOQL 2: the affected Accounts and their stored count. Accounts that no longer exist are
     *         not returned and are therefore never updated.
     * DML:    one update of the changed Accounts, only if there are any.
     */
    private static void recount(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();
        for (AggregateResult ar : [
                SELECT AccountId acctId, COUNT(Id) openCases
                FROM Case
                WHERE AccountId IN :accountIds
                  AND IsClosed = false
                GROUP BY AccountId
        ]) {
            Id acctId = (Id) ar.get('acctId');
            Integer openCases = (Integer) ar.get('openCases');
            openCountByAccount.put(acctId, openCases);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
                SELECT Id, FB_Open_Case_Count__c
                FROM Account
                WHERE Id IN :accountIds
        ]) {
            Integer target = 0;
            if (openCountByAccount.containsKey(acc.Id)) {
                target = openCountByAccount.get(acc.Id);
            }
            Integer current = acc.FB_Open_Case_Count__c == null
                ? null
                : Integer.valueOf(acc.FB_Open_Case_Count__c);
            if (current != target) {
                accountsToUpdate.add(new Account(
                    Id = acc.Id,
                    FB_Open_Case_Count__c = target
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
