public with sharing class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    /**
     * Parent accounts of the contacts in the current trigger execution, keyed by Id.
     * Reloaded on every execution by the Service action, which runs first in before insert.
     */
    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action (Trigger_Action__mdt order 1) that performs the single Account query
     * for the current before insert execution. Reloads the map on every execution because
     * later DML in the same transaction can involve other accounts.
     */
    public with sharing class Service implements TriggerAction.BeforeInsert {

        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (Contact c : (List<Contact>) triggerNew) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            TA_Contact_Queries queries = TA_Contact_Queries.getInstance();

            if (accountIds.isEmpty()) {
                queries.accountsById = new Map<Id, Account>();
                return;
            }

            queries.accountsById = new Map<Id, Account>([
                SELECT Id,
                    BillingStreet,
                    BillingCity,
                    BillingPostalCode,
                    BillingCountry,
                    AccountSource
                FROM Account
                WHERE Id IN :accountIds
                WITH USER_MODE
            ]);
        }
    }
}
